// Parallel driver: reads a JSON file [[slot, text], ...] and prints results.
// Reuses EXE/MK from the shared harness; extraction mirrors p.mjs phase()/phase5().
import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { EXE, MK } from '/tmp/probe/p.mjs';

const ORDER = ['a', 'b', 'c', 'd', 'e', 'f'];

function runAsync(args) {
  const argv = [];
  for (const k of ORDER) argv.push('--' + k, args[k] === undefined ? MK[k] : args[k]);
  return new Promise((res) => {
    execFile(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 }, (err, stdout, stderr) => {
      if (err) res('ERR(' + err.code + ')\n' + (stdout || '') + (stderr || ''));
      else res(stdout);
    });
  });
}

function extractPhase(slot, out) {
  const lines = out.split('\n');
  const pos = ORDER.indexOf(slot);
  let start = 0;
  for (let k = 0; k < pos; k++) start = lines.indexOf('<p>' + MK[ORDER[k]] + '</p>', start) + 1;
  const end = pos < 5 ? lines.indexOf('<p>' + MK[ORDER[pos + 1]] + '</p>', start)
                      : lines.indexOf('<h1>Combined Document</h1>', start);
  return lines.slice(start, end).join('\n');
}

function extractPhase5(out) {
  const lines = out.split('\n');
  let i = lines.length - 1;
  while (i >= 0 && lines[i] === '') i--;
  let j = i; while (j >= 0 && !lines[j].includes('</article>')) j--;
  const tail = lines.slice(j + 1, i + 1);
  const k = tail.lastIndexOf('<p>' + MK.e + '</p>');
  return tail.slice(k + 1).join('\n');
}

async function one([slot, text]) {
  if (slot === '5') {
    const args = { ...MK }; args.f = text;
    const out = await runAsync(args);
    if (out.startsWith('ERR(')) return out;
    return extractPhase5(out);
  }
  const args = { ...MK }; args[slot] = text;
  const out = await runAsync(args);
  if (out.startsWith('ERR(')) return out;
  return extractPhase(slot, out);
}

const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const results = new Array(cases.length);
let next = 0;
const CONC = 8;
await Promise.all(Array.from({ length: CONC }, async () => {
  while (true) {
    const i = next++;
    if (i >= cases.length) return;
    results[i] = await one(cases[i]);
  }
}));
for (let i = 0; i < cases.length; i++) {
  console.log('### [' + i + '] slot=' + cases[i][0] + ' IN=' + JSON.stringify(cases[i][1]));
  console.log('OUT=' + JSON.stringify(results[i]));
}

